      { q: "Куда в итоге едет пассажир?", options: ["Во Франкфурт", "В Базель", "В Берлин", "В Цюрих"], a: 1 },
      { q: "Почему пассажир может сесть на другой поезд?", options: ["Из-за опоздания привязка к поезду снята", "Он доплатил", "У него проездной", "Сотрудница поменяла билет"], a: 0 },
      { q: "Сколько денег можно вернуть при опоздании от 60 минут?", options: ["50 %", "100 %", "25 %", "Ничего"], a: 2 }
